import java.util.*;

interface FileSystemNode {
    String name();
    int getSize();
    void print(String indent);
}

final class File implements FileSystemNode {
    private final String name;
    private final int size;

    File(String name, int size) {
        this.name = name;
        this.size = size;
    }

    public String name() { return name; }

    public int getSize() { return size; } // Leaf: direct answer, no delegation.

    public void print(String indent) {
        System.out.println(indent + name + " (" + size + ")");
    }
}

final class Directory implements FileSystemNode {
    private final String name;
    private final List<FileSystemNode> children = new ArrayList<>();

    Directory(String name) { this.name = name; }

    public String name() { return name; }

    // Safe variant: add/remove live ONLY on Composite, not on the interface.
    public void add(FileSystemNode child) {
        Objects.requireNonNull(child);
        if (child == this || contains(child, this)) {
            throw new IllegalArgumentException("cycle: cannot add ancestor as child");
        }
        children.add(child);
    }

    public void remove(FileSystemNode child) { children.remove(child); }

    public int getSize() {
        int total = 0;
        for (FileSystemNode c : children) total += c.getSize(); // recursion happens here
        return total;
    }

    public void print(String indent) {
        System.out.println(indent + name + "/");
        for (FileSystemNode c : children) c.print(indent + "  ");
    }

    private static boolean contains(FileSystemNode root, FileSystemNode target) {
        if (root == target) return true;
        if (root instanceof Directory d) {
            for (FileSystemNode c : d.children) if (contains(c, target)) return true;
        }
        return false;
    }
}

// Client: zero branching on type.
class DiskUsage {
    static int totalFor(FileSystemNode node) { return node.getSize(); }
}
